// YAML dumper: replicates `yaml.dump(value, default_flow_style=False)`
// (PyYAML semantics: sort_keys=True, allow_unicode=False, indent 2,
// indentless block sequences) for the value model produced by
// safeLoad: null | boolean | number | string | YamlTimestamp | Array |
// plain Object.
//
// Everything is hand-written character scanning: no regular
// expressions, no JSON.*, no external modules.

import { YamlTimestamp } from './yamlTypes.mjs';

// ---------------------------------------------------------------------------
// Character helpers
// ---------------------------------------------------------------------------

// Characters PyYAML treats as whitespace for preceded/followed checks.
function isWsChar(ch) {
  return ch === '\0' || ch === ' ' || ch === '\t' || ch === '\r' ||
      ch === '\n' || ch === '\x85' || ch === '\u2028' || ch === '\u2029';
}

// Line break characters recognized by the emitter.
function isBreakChar(ch) {
  return ch === '\n' || ch === '\x85' || ch === '\u2028' || ch === '\u2029';
}

function isDigit(ch) {
  return ch >= '0' && ch <= '9';
}

// ---------------------------------------------------------------------------
// YAML 1.1 implicit resolution (PyYAML SafeResolver patterns), implemented as
// hand-written scanners. resolvePlain returns the tag a plain scalar would
// resolve to. Used to decide whether a string needs quoting and to classify
// mapping keys.
// ---------------------------------------------------------------------------

const BOOL_WORDS = [
  'yes', 'Yes', 'YES', 'no', 'No', 'NO',
  'true', 'True', 'TRUE', 'false', 'False', 'FALSE',
  'on', 'On', 'ON', 'off', 'Off', 'OFF',
];

function isBoolWord(s) {
  for (const w of BOOL_WORDS) {
    if (s === w) return true;
  }
  return false;
}

// [-+]?0b[0-1_]+ | [-+]?0[0-7_]+ | [-+]?(0|[1-9][0-9_]*)
// | [-+]?0x[0-9a-fA-F_]+ | [-+]?[1-9][0-9_]*(:[0-5]?[0-9])+
function isIntScalar(s) {
  let i = 0;
  if (s[0] === '-' || s[0] === '+') i = 1;
  const n = s.length;
  if (i >= n) return false;
  // 0b / 0x prefixed forms
  if (s[i] === '0' && i + 1 < n && (s[i + 1] === 'b' || s[i + 1] === 'x')) {
    const hexa = s[i + 1] === 'x';
    if (i + 2 >= n) return false;
    for (let j = i + 2; j < n; j++) {
      const c = s[j];
      if (c === '_') continue;
      if (hexa) {
        if (!isDigit(c) && !(c >= 'a' && c <= 'f') && !(c >= 'A' && c <= 'F')) return false;
      } else if (c !== '0' && c !== '1') {
        return false;
      }
    }
    return true;
  }
  if (s[i] === '0') {
    // `0` alone, or octal 0[0-7_]+
    if (i + 1 === n) return true;
    for (let j = i + 1; j < n; j++) {
      const c = s[j];
      if (c === '_') continue;
      if (!(c >= '0' && c <= '7')) return false;
    }
    return true;
  }
  if (!(s[i] >= '1' && s[i] <= '9')) return false;
  let j = i + 1;
  while (j < n && (isDigit(s[j]) || s[j] === '_')) j++;
  if (j === n) return true;
  // sexagesimal groups (: [0-5]? [0-9])+
  if (s[j] !== ':') return false;
  while (j < n) {
    if (s[j] !== ':') return false;
    j++;
    if (j >= n || !isDigit(s[j])) return false;
    if (s[j] > '5') {
      // only a single digit allowed in this group
      j++;
      if (j < n && isDigit(s[j])) return false;
    } else {
      j++;
      if (j < n && isDigit(s[j])) j++;
    }
  }
  return true;
}

// [-+]?[0-9][0-9_]*\.[0-9_]*([eE][-+][0-9]+)?
// | \.[0-9_]+([eE][-+][0-9]+)?
// | [-+]?[0-9][0-9_]*(:[0-5]?[0-9])+\.[0-9_]*
// | [-+]?\.(inf|Inf|INF) | \.(nan|NaN|NAN)
function isFloatScalar(s) {
  if (s === '.nan' || s === '.NaN' || s === '.NAN') return true;
  let i = 0;
  if (s[0] === '-' || s[0] === '+') i = 1;
  const n = s.length;
  if (i >= n) return false;
  if (s[i] === '.') {
    const rest = s.slice(i + 1);
    if (rest === 'inf' || rest === 'Inf' || rest === 'INF') return true;
    // \.[0-9_]+([eE][-+][0-9]+)?
    let j = i + 1;
    let seen = false;
    while (j < n && (isDigit(s[j]) || s[j] === '_')) { j++; seen = true; }
    if (!seen) return false;
    return scanExponent(s, j);
  }
  if (!isDigit(s[i])) return false;
  let j = i + 1;
  while (j < n && (isDigit(s[j]) || s[j] === '_')) j++;
  if (j < n && s[j] === ':') {
    // sexagesimal float: (: [0-5]? [0-9])+ \. [0-9_]*
    while (j < n && s[j] === ':') {
      j++;
      if (j >= n || !isDigit(s[j])) return false;
      if (s[j] > '5') {
        j++;
        if (j < n && isDigit(s[j])) return false;
      } else {
        j++;
        if (j < n && isDigit(s[j])) j++;
      }
    }
    if (j >= n || s[j] !== '.') return false;
    j++;
    while (j < n && (isDigit(s[j]) || s[j] === '_')) j++;
    return j === n;
  }
  if (j < n && s[j] === '.') {
    j++;
    while (j < n && (isDigit(s[j]) || s[j] === '_')) j++;
    return scanExponent(s, j);
  }
  return false;
}

// At position j, accept end-of-string or [eE][-+][0-9]+ then end.
function scanExponent(s, j) {
  const n = s.length;
  if (j === n) return true;
  if (s[j] !== 'e' && s[j] !== 'E') return false;
  j++;
  if (j >= n || (s[j] !== '-' && s[j] !== '+')) return false;
  j++;
  if (j >= n || !isDigit(s[j])) return false;
  while (j < n && isDigit(s[j])) j++;
  return j === n;
}

// [0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]
// | [0-9][0-9][0-9][0-9]-[0-9][0-9]?-[0-9][0-9]?([Tt]|[ \t]+)[0-9][0-9]?
//   :[0-9][0-9]:[0-9][0-9](\.[0-9]*)?([ \t]*(Z|[-+][0-9][0-9]?(:[0-9][0-9])?))?
function isTimestampScalar(s) {
  const n = s.length;
  let i = 0;
  for (let k = 0; k < 4; k++) {
    if (i >= n || !isDigit(s[i])) return false;
    i++;
  }
  if (i >= n || s[i] !== '-') return false;
  i++;
  if (i >= n || !isDigit(s[i])) return false;
  i++;
  if (i < n && isDigit(s[i])) i++; // 1-2 digit month
  if (i >= n || s[i] !== '-') return false;
  i++;
  if (i >= n || !isDigit(s[i])) return false;
  i++;
  if (i < n && isDigit(s[i])) i++; // 1-2 digit day
  if (i === n) {
    // date-only form requires exactly YYYY-MM-DD (2-digit month and day)
    return n === 10;
  }
  // separator: T/t or run of space/tab
  if (s[i] === 'T' || s[i] === 't') {
    i++;
  } else if (s[i] === ' ' || s[i] === '\t') {
    while (i < n && (s[i] === ' ' || s[i] === '\t')) i++;
  } else {
    return false;
  }
  // hour: 1-2 digits
  if (i >= n || !isDigit(s[i])) return false;
  i++;
  if (i < n && isDigit(s[i])) i++;
  if (i >= n || s[i] !== ':') return false;
  i++;
  // minute: exactly 2 digits
  if (i + 1 >= n || !isDigit(s[i]) || !isDigit(s[i + 1])) return false;
  i += 2;
  if (i >= n || s[i] !== ':') return false;
  i++;
  // second: exactly 2 digits
  if (i + 1 >= n || !isDigit(s[i]) || !isDigit(s[i + 1])) return false;
  i += 2;
  // optional fraction: . digits*
  if (i < n && s[i] === '.') {
    i++;
    while (i < n && isDigit(s[i])) i++;
  }
  // optional timezone
  if (i === n) return true;
  while (i < n && (s[i] === ' ' || s[i] === '\t')) i++;
  if (i === n) return true;
  if (s[i] === 'Z') return i + 1 === n;
  if (s[i] === '-' || s[i] === '+') {
    i++;
    if (i >= n || !isDigit(s[i])) return false;
    i++;
    if (i < n && isDigit(s[i])) i++; // 1-2 digit hour offset
    if (i === n) return true;
    if (s[i] !== ':') return false;
    i++;
    if (i + 1 >= n || !isDigit(s[i]) || !isDigit(s[i + 1])) return false;
    i += 2;
    return i === n;
  }
  return false;
}

function resolvePlain(s) {
  if (s === '' || s === '~' || s === 'null' || s === 'Null' || s === 'NULL') return 'null';
  if (isBoolWord(s)) return 'bool';
  if (s === '<<') return 'merge';
  if (s === '=') return 'value';
  if (s === '!' || s === '&' || s === '*') return 'yaml';
  if (isIntScalar(s)) return 'int';
  if (isFloatScalar(s)) return 'float';
  if (isTimestampScalar(s)) return 'timestamp';
  return 'str';
}

// ---------------------------------------------------------------------------
// Scalar value parsing (for canonicalizing non-string mapping keys)
// ---------------------------------------------------------------------------

function parseYamlInt(s) {
  // Returns a BigInt.
  let i = 0;
  let neg = false;
  if (s[0] === '-' || s[0] === '+') {
    neg = s[0] === '-';
    i = 1;
  }
  let body = '';
  for (let j = i; j < s.length; j++) {
    if (s[j] !== '_') body += s[j];
  }
  let v;
  if (body.startsWith('0x')) {
    v = BigInt(body);
  } else if (body.startsWith('0b')) {
    v = 0n;
    for (let j = 2; j < body.length; j++) v = v * 2n + BigInt(body[j] === '1' ? 1 : 0);
  } else if (body.indexOf(':') !== -1) {
    // sexagesimal
    v = 0n;
    let cur = '';
    for (let j = 0; j <= body.length; j++) {
      const c = j < body.length ? body[j] : ':';
      if (c === ':') {
        v = v * 60n + BigInt(cur);
        cur = '';
      } else {
        cur += c;
      }
    }
  } else if (body.length > 1 && body[0] === '0') {
    v = 0n;
    for (let j = 1; j < body.length; j++) v = v * 8n + BigInt(body.charCodeAt(j) - 48);
  } else {
    v = BigInt(body);
  }
  return neg ? -v : v;
}

function parseYamlFloat(s) {
  let i = 0;
  let neg = false;
  if (s[0] === '-' || s[0] === '+') {
    neg = s[0] === '-';
    i = 1;
  }
  const rest = s.slice(i);
  if (rest === '.inf' || rest === '.Inf' || rest === '.INF') return neg ? -Infinity : Infinity;
  if (rest === '.nan' || rest === '.NaN' || rest === '.NAN') return NaN;
  let clean = '';
  for (let j = 0; j < rest.length; j++) {
    if (rest[j] !== '_') clean += rest[j];
  }
  let v;
  if (clean.indexOf(':') !== -1) {
    // sexagesimal float: groups base 60, fraction on the last group
    const dotAt = clean.indexOf('.');
    const intPart = dotAt === -1 ? clean : clean.slice(0, dotAt);
    const fracPart = dotAt === -1 ? '' : clean.slice(dotAt + 1);
    v = 0;
    let cur = '';
    for (let j = 0; j <= intPart.length; j++) {
      const c = j < intPart.length ? intPart[j] : ':';
      if (c === ':') {
        v = v * 60 + Number(cur);
        cur = '';
      } else {
        cur += c;
      }
    }
    if (fracPart !== '') v += Number('0.' + fracPart);
  } else {
    v = Number(clean);
  }
  return neg ? -v : v;
}

// ---------------------------------------------------------------------------
// Python-repr float formatting (PyYAML represent_float)
// ---------------------------------------------------------------------------

function formatFloat(n) {
  if (Number.isNaN(n)) return '.nan';
  if (n === Infinity) return '.inf';
  if (n === -Infinity) return '-.inf';
  let sign = '';
  let v = n;
  if (v < 0 || Object.is(v, -0)) {
    sign = '-';
    v = -v;
  }
  if (v === 0) return sign + '0.0';
  // Extract shortest round-trip digits from the JS rendering.
  const s = String(v); // e.g. "0.001", "1e+21", "123.5"
  let mant = s;
  let exp = 0;
  let eAt = -1;
  for (let i = 0; i < s.length; i++) {
    if (s[i] === 'e' || s[i] === 'E') { eAt = i; break; }
  }
  if (eAt !== -1) {
    mant = s.slice(0, eAt);
    exp = Number(s.slice(eAt + 1));
  }
  let intPart = mant;
  let fracPart = '';
  const dotAt = mant.indexOf('.');
  if (dotAt !== -1) {
    intPart = mant.slice(0, dotAt);
    fracPart = mant.slice(dotAt + 1);
  }
  let raw = intPart + fracPart;
  let decpt = intPart.length + exp; // value = 0.raw * 10^decpt (raw unnormalized)
  // strip leading zeros
  let lead = 0;
  while (lead < raw.length && raw[lead] === '0') lead++;
  raw = raw.slice(lead);
  decpt -= lead;
  // strip trailing zeros
  let end = raw.length;
  while (end > 1 && raw[end - 1] === '0') end--;
  const digits = raw.slice(0, end);
  let out;
  if (decpt <= -4 || decpt > 16) {
    // scientific: d[.ddd]e±XX (exponent at least two digits)
    let m = digits[0];
    if (digits.length > 1) m += '.' + digits.slice(1);
    const e = decpt - 1;
    const esign = e < 0 ? '-' : '+';
    let edigits = String(Math.abs(e));
    if (edigits.length < 2) edigits = '0' + edigits;
    out = m + 'e' + esign + edigits;
  } else if (decpt <= 0) {
    out = '0.';
    for (let i = 0; i < -decpt; i++) out += '0';
    out += digits;
  } else if (decpt >= digits.length) {
    out = digits;
    for (let i = digits.length; i < decpt; i++) out += '0';
    out += '.0';
  } else {
    out = digits.slice(0, decpt) + '.' + digits.slice(decpt);
  }
  // PyYAML represent_float: lowercase, and insert ".0" before a bare exponent.
  if (out.indexOf('.') === -1 && out.indexOf('e') !== -1) {
    out = out.split('e').join('.0e');
  }
  return sign + out;
}

function formatIntNumber(n) {
  // Integer-valued JS number: decimal digits when exactly representable.
  if (Math.abs(n) < 1e21) return String(n);
  return formatFloat(n); // precision already lost at this magnitude
}

// ---------------------------------------------------------------------------
// Scalar analysis (PyYAML emitter.analyze_scalar, specialized to
// allow_unicode=False and block context)
// ---------------------------------------------------------------------------

const LEADING_INDICATORS = '#,;:[]{}&*!|>\'"%@`';

function analyzeScalar(text) {
  const analysis = {
    empty: false,
    multiline: false,
    allowBlockPlain: true,
    allowSingleQuoted: true,
  };
  if (text === '') {
    analysis.empty = true;
    analysis.allowBlockPlain = false;
    return analysis;
  }
  const chars = Array.from(text); // iterate by code point
  const n = chars.length;
  let blockIndicators = false;
  let lineBreaks = false;
  let special = false;
  let leadingSpace = false;
  let leadingBreak = false;
  let trailingSpace = false;
  let trailingBreak = false;
  let breakSpace = false;
  let spaceBreak = false;

  if (text.startsWith('---') || text.startsWith('...')) blockIndicators = true;

  let preceded = true;
  let followed = n === 1 || isWsChar(chars[1]);
  const c0 = chars[0];
  if (LEADING_INDICATORS.indexOf(c0) !== -1) blockIndicators = true;
  if ((c0 === '?' || c0 === ':') && followed) blockIndicators = true;
  if (c0 === '-' && followed) blockIndicators = true;

  let prevSpace = false;
  let prevBreak = false;
  for (let i = 0; i < n; i++) {
    const ch = chars[i];
    if (ch === ':' && followed) blockIndicators = true;
    if (ch === '#' && preceded) blockIndicators = true;
    const cp = ch.codePointAt(0);
    if (isBreakChar(ch)) lineBreaks = true;
    if (!(ch === '\n' || (cp >= 0x20 && cp <= 0x7E))) special = true;
    if (ch === ' ') {
      if (i === 0) leadingSpace = true;
      if (i === n - 1) trailingSpace = true;
      if (prevBreak) breakSpace = true;
      prevSpace = true;
      prevBreak = false;
    } else if (isBreakChar(ch)) {
      if (i === 0) leadingBreak = true;
      if (i === n - 1) trailingBreak = true;
      if (prevSpace) spaceBreak = true;
      prevSpace = false;
      prevBreak = true;
    } else {
      prevSpace = false;
      prevBreak = false;
    }
    preceded = isWsChar(ch);
    followed = i + 1 >= n || isWsChar(chars[i + 1]);
  }

  let allowBlockPlain = true;
  let allowSingleQuoted = true;
  if (leadingSpace || leadingBreak || trailingSpace || trailingBreak) allowBlockPlain = false;
  if (breakSpace) {
    allowBlockPlain = false;
    allowSingleQuoted = false;
  }
  if (spaceBreak || special) {
    allowBlockPlain = false;
    allowSingleQuoted = false;
  }
  if (lineBreaks) allowBlockPlain = false;
  if (blockIndicators) allowBlockPlain = false;

  analysis.multiline = lineBreaks;
  analysis.allowBlockPlain = allowBlockPlain;
  analysis.allowSingleQuoted = allowSingleQuoted;
  return analysis;
}

// ---------------------------------------------------------------------------
// Emitter
// ---------------------------------------------------------------------------

const BEST_WIDTH = 80;
const BEST_INDENT = 2;

class Emitter {
  constructor() {
    this.out = [];
    this.line = 0;
    this.column = 0;
    this.whitespace = true;
    this.indention = true;
    this.openEnded = false;
    this.indent = null;
    this.indents = [];
  }

  writeRaw(data) {
    this.out.push(data);
  }

  writeIndicator(indicator, needWhitespace, whitespace, indention) {
    let data = indicator;
    if (!(this.whitespace || !needWhitespace)) data = ' ' + indicator;
    this.whitespace = whitespace;
    this.indention = this.indention && indention;
    this.column += data.length;
    this.openEnded = false;
    this.out.push(data);
  }

  writeIndent() {
    const indent = this.indent === null ? 0 : this.indent;
    if (!this.indention || this.column > indent ||
        (this.column === indent && !this.whitespace)) {
      this.writeLineBreak();
    }
    if (this.column < indent) {
      this.whitespace = true;
      const data = ' '.repeat(indent - this.column);
      this.column = indent;
      this.out.push(data);
    }
  }

  writeLineBreak(br) {
    this.whitespace = true;
    this.indention = true;
    this.line += 1;
    this.column = 0;
    this.out.push(br === undefined ? '\n' : br);
  }

  // Continuation lines of folded plain/single-quoted scalars and of broken
  // double-quoted scalars are indented two extra spaces past the current
  // structural indent (verified against the reference implementation).
  writeFoldContinuation() {
    this.writeLineBreak();
    const target = (this.indent === null ? 0 : this.indent) + BEST_INDENT;
    if (this.column < target) {
      this.whitespace = true;
      const data = ' '.repeat(target - this.column);
      this.column = target;
      this.out.push(data);
    }
  }

  increaseIndent(flow, indentless) {
    this.indents.push(this.indent);
    if (this.indent === null) {
      this.indent = flow ? BEST_INDENT : 0;
    } else if (!indentless) {
      this.indent += BEST_INDENT;
    }
  }

  writePlain(text, split, rootContext) {
    if (rootContext) this.openEnded = true;
    if (text === '') return;
    if (!this.whitespace) {
      this.column += 1;
      this.out.push(' ');
    }
    this.whitespace = false;
    this.indention = false;
    let spaces = false;
    let start = 0;
    let end = 0;
    const n = text.length;
    while (end <= n) {
      const ch = end < n ? text[end] : null;
      if (spaces) {
        if (ch !== ' ') {
          if (start + 1 === end && this.column > BEST_WIDTH && split &&
              start !== 0 && end !== n) {
            this.writeFoldContinuation();
          } else {
            const data = text.slice(start, end);
            this.column += data.length;
            this.out.push(data);
          }
          start = end;
          spaces = false;
        }
      } else if (ch === null || ch === ' ' || isBreakChar(ch)) {
        const data = text.slice(start, end);
        this.column += data.length;
        this.out.push(data);
        start = end;
      }
      if (ch === ' ') spaces = true;
      end++;
    }
  }

  writeSingleQuoted(text, split) {
    this.writeIndicator('\'', true, false, false);
    let spaces = false;
    let breaks = false;
    let start = 0;
    let end = 0;
    const n = text.length;
    while (end <= n) {
      const ch = end < n ? text[end] : null;
      if (spaces) {
        if (ch === null || ch !== ' ') {
          if (start + 1 === end && this.column > BEST_WIDTH && split &&
              start !== 0 && end !== n) {
            this.writeFoldContinuation();
          } else {
            const data = text.slice(start, end);
            this.column += data.length;
            this.out.push(data);
          }
          start = end;
          spaces = false;
        }
      } else if (breaks) {
        if (ch === null || !isBreakChar(ch)) {
          if (text[start] === '\n') this.writeLineBreak();
          const run = text.slice(start, end);
          for (let k = 0; k < run.length; k++) {
            if (run[k] === '\n') this.writeLineBreak();
            else this.writeLineBreak(run[k]);
          }
          this.writeFoldContinuation();
          start = end;
          breaks = false;
        }
      } else if (ch === null || ch === ' ' || isBreakChar(ch) || ch === '\'') {
        if (start < end) {
          const data = text.slice(start, end);
          this.column += data.length;
          this.out.push(data);
          start = end;
        }
      }
      if (ch === '\'') {
        this.column += 2;
        this.out.push('\'\'');
        start = end + 1;
      }
      if (ch === ' ') spaces = true;
      else if (ch !== null && isBreakChar(ch)) breaks = true;
      end++;
    }
    this.writeIndicator('\'', false, false, false);
  }

  writeDoubleQuoted(text, split) {
    this.writeIndicator('"', true, false, false);
    const chars = Array.from(text); // code points
    const n = chars.length;
    let start = 0;
    let end = 0;
    while (end <= n) {
      const ch = end < n ? chars[end] : null;
      const cp = ch === null ? 0 : ch.codePointAt(0);
      if (ch === null || ch === '"' || ch === '\\' ||
          ch === '\x85' || ch === '\u2028' || ch === '\u2029' || ch === '\uFEFF' ||
          !(cp >= 0x20 && cp <= 0x7E)) {
        if (start < end) {
          const data = chars.slice(start, end).join('');
          this.column += data.length;
          this.out.push(data);
          start = end;
        }
        if (ch !== null) {
          let data;
          const esc = ESCAPE_REPLACEMENTS[ch];
          if (esc !== undefined) {
            data = '\\' + esc;
          } else if (cp <= 0xFF) {
            data = '\\x' + cp.toString(16).toUpperCase().padStart(2, '0');
          } else if (cp <= 0xFFFF) {
            data = '\\u' + cp.toString(16).toUpperCase().padStart(4, '0');
          } else {
            data = '\\U' + cp.toString(16).toUpperCase().padStart(8, '0');
          }
          this.column += data.length;
          this.out.push(data);
          start = end + 1;
        }
      }
      if (end > 0 && end < n - 1 && (ch === ' ' || start >= end) &&
          this.column + (end - start) > BEST_WIDTH && split) {
        let data = chars.slice(start, end).join('') + '\\';
        if (start < end) start = end;
        this.column += data.length;
        this.out.push(data);
        this.writeFoldContinuation();
        this.whitespace = false;
        this.indention = false;
        if (chars[start] === ' ') {
          this.column += 1;
          this.out.push('\\');
        }
      }
      end++;
    }
    this.writeIndicator('"', false, false, false);
  }
}

const ESCAPE_REPLACEMENTS = {
  '\0': '0',
  '\x07': 'a',
  '\x08': 'b',
  '\t': 't',
  '\n': 'n',
  '\x0B': 'v',
  '\x0C': 'f',
  '\r': 'r',
  '\x1B': 'e',
  '"': '"',
  '\\': '\\',
  '\x85': 'N',
  '\xA0': '_',
  '\u2028': 'L',
  '\u2029': 'P',
};

// ---------------------------------------------------------------------------
// Mapping key classification and sorting.
//
// Keys arrive as JS strings; their YAML type is recovered through implicit
// resolution. Non-string keys are emitted in canonical form (int in decimal,
// bool lowercase, float in Python repr style, null as `null`, timestamps in
// their original text), mirroring how PyYAML dumps the constructed values.
//
// Sorting mirrors CPython's sorted() on the constructed keys: numeric keys
// (int/float/bool) compare numerically, strings by code point, timestamps
// among themselves; comparing incomparable types raises TypeError in Python,
// in which case PyYAML keeps the original insertion order. We simulate
// CPython's binary insertion sort (used for short lists) so that even the
// failure behavior matches.
// ---------------------------------------------------------------------------

function classifyKey(raw) {
  const tag = resolvePlain(raw);
  if (tag === 'int') {
    const v = parseYamlInt(raw);
    return { group: 'num', num: Number(v), text: v.toString() };
  }
  if (tag === 'float') {
    const v = parseYamlFloat(raw);
    return { group: 'num', num: v, text: formatFloat(v) };
  }
  if (tag === 'bool') {
    const t = raw === 'yes' || raw === 'Yes' || raw === 'YES' ||
        raw === 'true' || raw === 'True' || raw === 'TRUE' ||
        raw === 'on' || raw === 'On' || raw === 'ON';
    return { group: 'num', num: t ? 1 : 0, text: t ? 'true' : 'false' };
  }
  if (tag === 'null' && raw !== '') {
    return { group: 'null', num: 0, text: 'null' };
  }
  if (tag === 'timestamp') {
    return { group: 'ts', num: 0, text: raw };
  }
  // 'merge', 'value', 'yaml' resolve to plain strings after construction,
  // and the empty key is kept as a string (quoted form).
  return { group: 'str', num: 0, text: raw };
}

// Code-point less-than for two strings (Python str comparison).
function codePointLt(a, b) {
  const ca = Array.from(a);
  const cb = Array.from(b);
  const n = Math.min(ca.length, cb.length);
  for (let i = 0; i < n; i++) {
    const pa = ca[i].codePointAt(0);
    const pb = cb[i].codePointAt(0);
    if (pa !== pb) return pa < pb;
  }
  return ca.length < cb.length;
}

// Python `<` on two classified keys; throws on incomparable types.
function keyLessThan(a, b) {
  if (a.group === 'num' && b.group === 'num') return a.num < b.num;
  if (a.group === 'str' && b.group === 'str') return codePointLt(a.key, b.key);
  if (a.group === 'ts' && b.group === 'ts') return a.key < b.key;
  throw new Error('unorderable mapping keys');
}

// CPython binarysort with TypeError fallback to the original order.
function sortKeys(entries) {
  const a = entries.slice();
  try {
    for (let i = 1; i < a.length; i++) {
      const pivot = a[i];
      let lo = 0;
      let hi = i;
      while (lo < hi) {
        const mid = (lo + hi) >> 1;
        if (keyLessThan(pivot, a[mid])) hi = mid;
        else lo = mid + 1;
      }
      for (let j = i; j > lo; j--) a[j] = a[j - 1];
      a[lo] = pivot;
    }
    return a;
  } catch (e) {
    return entries;
  }
}

// ---------------------------------------------------------------------------
// Serialization
// ---------------------------------------------------------------------------

function isCollection(node) {
  return Array.isArray(node) || isPlainObject(node);
}

function isPlainObject(node) {
  if (node === null || typeof node !== 'object') return false;
  if (node instanceof YamlTimestamp) return false;
  const proto = Object.getPrototypeOf(node);
  return proto === Object.prototype || proto === null;
}

export function dump(value) {
  // Anchor assignment (PyYAML serializer.anchor_node): a collection that is
  // referenced more than once gets an `idNNN` anchor, assigned in DFS
  // pre-order at the second encounter. Repeated scalars are simply emitted
  // twice.
  const anchors = new Map();
  let lastAnchorId = 0;
  function anchorNode(node) {
    if (!isCollection(node)) return;
    if (anchors.has(node)) {
      if (anchors.get(node) === null) {
        lastAnchorId += 1;
        let digits = String(lastAnchorId);
        while (digits.length < 3) digits = '0' + digits;
        anchors.set(node, 'id' + digits);
      }
      return;
    }
    anchors.set(node, null);
    if (Array.isArray(node)) {
      for (const item of node) anchorNode(item);
    } else {
      for (const k of Object.keys(node)) anchorNode(node[k]);
    }
  }

  // Sort mapping keys recursively (before anchor traversal, matching
  // PyYAML where sorting happens in the representer).
  function sortMappingKeys(node) {
    if (Array.isArray(node)) {
      for (const item of node) sortMappingKeys(item);
      return node;
    }
    if (!isPlainObject(node)) return node;
    const entries = [];
    for (const k of Object.keys(node)) {
      const cls = classifyKey(k);
      entries.push({ key: k, group: cls.group, num: cls.num, text: cls.text, value: node[k] });
    }
    const sorted = sortKeys(entries);
    for (const e of sorted) sortMappingKeys(e.value);
    return sorted;
  }

  const root = sortMappingKeys(value);
  anchorNode(root);

  const em = new Emitter();
  const serialized = new Set();

  function emitScalarText(text, implicitPlain, ctx) {
    const analysis = analyzeScalar(text);
    let style;
    if (implicitPlain &&
        !(ctx.simpleKey && (analysis.empty || analysis.multiline)) &&
        analysis.allowBlockPlain) {
      style = '';
    } else if (analysis.allowSingleQuoted && !(ctx.simpleKey && analysis.multiline)) {
      style = '\'';
    } else {
      style = '"';
    }
    const split = !ctx.simpleKey;
    if (style === '"') em.writeDoubleQuoted(text, split);
    else if (style === '\'') em.writeSingleQuoted(text, split);
    else em.writePlain(text, split, ctx.root === true);
  }

  function scalarTextOf(node) {
    // Returns [text, implicitPlain] for a scalar value.
    if (node === null || node === undefined) return ['null', true];
    if (typeof node === 'boolean') return [node ? 'true' : 'false', true];
    if (typeof node === 'number') {
      if (Number.isInteger(node)) return [formatIntNumber(node), true];
      return [formatFloat(node), true];
    }
    if (typeof node === 'bigint') return [node.toString(), true];
    if (node instanceof YamlTimestamp) return [node.text, true];
    if (typeof node === 'string') return [node, resolvePlain(node) === 'str'];
    throw new Error('cannot dump value of type ' + typeof node);
  }

  function emitNode(node, ctx) {
    // Sorted mappings are represented as arrays of entries.
    if (Array.isArray(node) && node.length >= 0 && !isEntryList(node)) {
      emitSequence(node, ctx);
      return;
    }
    if (isEntryList(node)) {
      emitMapping(node, ctx);
      return;
    }
    if (isCollection(node)) {
      // unreachable: sortMappingKeys normalized all objects
      throw new Error('unexpected object');
    }
    emitScalarText(...(() => { const [t, p] = scalarTextOf(node); return [t, p, ctx]; })());
  }

  function isEntryList(node) {
    return Array.isArray(node) && node.__yamlEntries === true;
  }

  function processAnchorAndCheckAlias(node) {
    // Returns true if an alias was emitted.
    if (serialized.has(node)) {
      const anchor = anchors.get(node);
      em.writeIndicator('*' + anchor, true, false, false);
      return true;
    }
    serialized.add(node);
    const anchor = anchors.get(node);
    if (anchor !== null && anchor !== undefined) {
      em.writeIndicator('&' + anchor, true, false, false);
    }
    return false;
  }

  function emitSequence(node, ctx) {
    if (processAnchorAndCheckAlias(node)) return;
    if (node.length === 0) {
      em.writeIndicator('[', true, true, false);
      em.writeIndicator(']', false, false, false);
      return;
    }
    const indentless = ctx.mapping === true && !em.indention;
    em.increaseIndent(false, indentless);
    for (const item of node) {
      em.writeIndent();
      em.writeIndicator('-', true, false, true);
      emitNode(item, { sequence: true });
    }
    em.indent = em.indents.pop();
  }

  function emitMapping(entries, ctx) {
    if (processAnchorAndCheckAlias(entries.__source)) return;
    if (entries.length === 0) {
      em.writeIndicator('{', true, true, false);
      em.writeIndicator('}', false, false, false);
      return;
    }
    em.increaseIndent(false, false);
    for (const e of entries) {
      em.writeIndent();
      // Simple keys: scalar with length < 128 (our keys are always scalar).
      if (e.text.length < 128) {
        emitKeyScalar(e, true);
        em.writeIndicator(':', false, false, false);
        emitNode(e.value, { mapping: true });
      } else {
        em.writeIndicator('?', true, false, true);
        emitKeyScalar(e, false);
        em.writeIndent();
        em.writeIndicator(':', true, false, true);
        emitNode(e.value, { mapping: true });
      }
    }
    em.indent = em.indents.pop();
  }

  function emitKeyScalar(entry, simpleKey) {
    if (entry.group === 'str') {
      emitScalarText(entry.text, resolvePlain(entry.key) === 'str', { mapping: true, simpleKey });
    } else {
      emitScalarText(entry.text, true, { mapping: true, simpleKey });
    }
  }

  // Represent mappings as tagged entry lists so anchor identity is preserved.
  function normalize(node) {
    if (Array.isArray(node)) return node;
    if (isPlainObject(node)) {
      const entries = sortKeys(Object.keys(node).map((k) => {
        const cls = classifyKey(k);
        return { key: k, group: cls.group, num: cls.num, text: cls.text, value: node[k] };
      }));
      for (const e of entries) e.value = normalize(e.value);
      Object.defineProperty(entries, '__yamlEntries', { value: true, enumerable: false });
      entries.__source = node;
      return entries;
    }
    return node;
  }

  // Rebuild: normalize first (sorting happens once, structure shared).
  const normalizedRoot = normalize(value);

  // Anchor traversal must run on the normalized structure in document order.
  function anchorNode2(node) {
    const isArr = Array.isArray(node);
    if (!isArr) return;
    const src = node.__yamlEntries ? node.__source : node;
    if (anchors.has(src)) {
      if (anchors.get(src) === null) {
        lastAnchorId += 1;
        let digits = String(lastAnchorId);
        while (digits.length < 3) digits = '0' + digits;
        anchors.set(src, 'id' + digits);
      }
      return;
    }
    anchors.set(src, null);
    if (node.__yamlEntries) {
      for (const e of node) anchorNode2(e.value);
    } else {
      for (const item of node) anchorNode2(item);
    }
  }
  anchorNode2(normalizedRoot);

  emitNode(normalizedRoot, { root: true });
  em.writeIndent();
  if (em.openEnded) {
    em.writeIndicator('...', true, false, false);
    em.writeIndent();
  }
  return em.out.join('');
}
